import assert from 'node:assert/strict';
import {fork} from 'node:child_process';
const fen='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
let priority=false,startedAt;
if(process.argv[2]==='maia'){
 const {createCancellableMaia}=await import('/app/scripts/cancellable-maia.mjs');
 const inference=createCancellableMaia({launch:()=>{const child=fork('/app/scripts/maia-inference-child.mjs',[],{execArgv:[],stdio:['ignore','inherit','inherit','ipc']});child.on('message',m=>{if(m.started && startedAt===undefined){startedAt=performance.now();priority=true;}});return child;}});
 try{const cancelled=await inference.analyze(fen,1500,async()=>!priority).catch(e=>e);assert.equal(cancelled.code,'STUDY_PREEMPTED');const elapsed=performance.now()-startedAt;assert(elapsed<=250,`Maia yield ${elapsed}`);priority=false;const moves=await inference.analyze(fen,1500,async()=>!priority);assert.equal(moves.length,20);assert(Math.abs(moves.reduce((t,m)=>t+m.probability,0)-1)<.0001);console.log(JSON.stringify({kind:'maia',yield_ms:elapsed,legal_moves:moves.length}));}finally{inference.close();}
}else{
 const {createStockfishProcess}=await import('/app/scripts/stockfish-process.mjs');const {createEngineSearch}=await import('/app/scripts/engine-search.mjs');let engine=await createStockfishProcess();
 try{engine.uci('uci');engine.uci('setoption name Threads value 1');engine.uci('setoption name Hash value 32');engine.uci('isready');const searches=createEngineSearch(engine,async()=>({active:priority,available:true,study_only_mode:false}));const job={request:{position_start_fen:fen,position_prefix_uci:[],depth:99,multipv:1}};const cancelled=searches.evaluate(job,'engine_game').catch(e=>e);const listen=engine.listen;engine.listen=t=>{listen(t);if(startedAt===undefined && t.startsWith('info ')&&t.includes(' pv ')){startedAt=performance.now();priority=true;}};assert.equal((await cancelled).diagnostics.outcome,'preempted');const elapsed=performance.now()-startedAt;assert(elapsed<=250,`Stockfish yield ${elapsed}`);const restarted=searches.fatalEngineError;if(restarted){engine.terminate();engine=await createStockfishProcess();engine.uci('uci');engine.uci('setoption name Threads value 1');engine.uci('setoption name Hash value 32');engine.uci('isready');}priority=false;const quietSearches=restarted?createEngineSearch(engine,async()=>({active:priority,available:true,study_only_mode:false})):searches;const result=await quietSearches.evaluate({...job,request:{...job.request,depth:4}},'engine_game');assert(result.report.complete);console.log(JSON.stringify({kind:'stockfish',yield_ms:elapsed,depth:4,restarted_after_hard_stop:restarted}));}finally{engine.terminate();}
}
